// Package gxstyles writes the generated package that embeds the built
// stylesheet (REQ-STY-02). The app's main calls gx.SetStylesheet with
// gxstyles.CSS().
package gxstyles

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/alternayte/gx/internal/tailwind"
)

// Dir and File name the generated package.
const (
	Dir  = "gxstyles"
	File = "styles_gx.go"
)

// Path returns the generated file path under root.
func Path(root string) string { return filepath.Join(root, Dir, File) }

// ThemePath returns the theme file the app owns.
func ThemePath(root string) string { return filepath.Join(root, "app", "theme.css") }

// Generate returns the Go source that embeds css, for an app with no
// widget.
func Generate(css []byte) []byte { return GenerateAll(css, nil) }

// GenerateAll returns the Go source that embeds the stylesheet of the app
// and the stylesheet of each widget, by the tag of the widget (REQ-ISL-11).
func GenerateAll(css []byte, widgets map[string][]byte) []byte {
	var b strings.Builder
	b.WriteString("// Code generated by gx. DO NOT EDIT.\n\n")
	b.WriteString("package gxstyles\n\n")
	b.WriteString("// CSS returns the built stylesheet (REQ-STY-02).\n")
	b.WriteString("func CSS() []byte { return []byte(stylesheet) }\n\n")
	b.WriteString("// Widgets returns the built stylesheet of each widget, by its tag\n")
	b.WriteString("// (REQ-ISL-11). Give it to gx.SetWidgetStylesheets.\n")
	b.WriteString("func Widgets() map[string][]byte {\n")
	tags := make([]string, 0, len(widgets))
	for tag := range widgets {
		tags = append(tags, tag)
	}
	sort.Strings(tags)
	if len(tags) == 0 {
		b.WriteString("\treturn map[string][]byte{}\n")
	} else {
		b.WriteString("\treturn map[string][]byte{\n")
		for _, tag := range tags {
			b.WriteString("\t\t" + strconv.Quote(tag) + ": []byte(" + strconv.Quote(string(widgets[tag])) + "),\n")
		}
		b.WriteString("\t}\n")
	}
	b.WriteString("}\n\n")
	b.WriteString("const stylesheet = " + strconv.Quote(string(css)) + "\n")
	return []byte(b.String())
}

// WidgetClassesPath returns the file with the class list of each widget,
// which the compiler writes.
func WidgetClassesPath(root string) string {
	return filepath.Join(root, ".gx", "widget-classes.json")
}

// BuildWidgets builds the stylesheet of each widget of the app: Tailwind
// reads the theme of the app and the class list of one widget, and ShadowCSS
// makes the result work in a shadow root (REQ-ISL-11). The build is minified
// in each mode, because ShadowCSS reads that form.
func BuildWidgets(ctx context.Context, root string) (map[string][]byte, error) {
	data, err := os.ReadFile(WidgetClassesPath(root))
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if len(bytes.TrimSpace(data)) == 0 {
		// The app has no widget.
		return nil, nil
	}
	var lists map[string][]string
	if err := json.Unmarshal(data, &lists); err != nil {
		return nil, errors.New("gxstyles: " + WidgetClassesPath(root) + " is not the class list of the widgets; run gx generate")
	}
	if len(lists) == 0 {
		return nil, nil
	}
	themePath := ThemePath(root)
	theme, err := os.ReadFile(themePath)
	if err != nil {
		return nil, err
	}
	dir := filepath.Join(root, ".gx", "widgets")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	tw := &tailwind.Manager{Root: root}
	out := map[string][]byte{}
	for tag, classes := range lists {
		list := filepath.Join(dir, tag+".txt")
		if err := os.WriteFile(list, []byte(strings.Join(classes, "\n")+"\n"), 0o644); err != nil {
			return nil, err
		}
		input, err := widgetTheme(theme, filepath.ToSlash(list))
		if err != nil {
			return nil, err
		}
		// The input comes on the standard input, from the directory of
		// the theme, so each relative path of the theme holds.
		css, err := tw.BuildInput(ctx, input, filepath.Dir(themePath), filepath.Join(dir, tag+".css"))
		if err != nil {
			return nil, err
		}
		if out[tag], err = ShadowCSS(css); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Build runs Tailwind when the app owns app/theme.css and writes the
// generated stylesheet package (REQ-STY-02). It reports false when the app
// has no theme.
func Build(ctx context.Context, root string, minify bool) (bool, error) {
	if abs, err := filepath.Abs(root); err == nil {
		root = abs
	}
	theme := ThemePath(root)
	if _, err := os.Stat(theme); err != nil {
		return false, nil
	}
	css, err := (&tailwind.Manager{Root: root}).Build(ctx, theme, minify)
	if err != nil {
		return false, err
	}
	widgets, err := BuildWidgets(ctx, root)
	if err != nil {
		return false, err
	}
	path := Path(root)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return false, err
	}
	if err := os.WriteFile(path, GenerateAll(css, widgets), 0o644); err != nil {
		return false, err
	}
	return true, nil
}
